def lease_occupancy(limit, requests):
    if limit < 0:
        raise ValueError("limit")
    live, out = [], []
    for st, en, seats in requests:
        if en <= st or seats < 0:
            raise ValueError("lease")
        ok = sum(it[2] for it in live) + seats <= limit
        live = [it for it in live if it[1] > st]
        if ok:
            live.append([st, en, seats])
        out.append(ok)
    return out

