def clipped_band_sum(low, high, spans):
    if high <= low:
        raise ValueError("invalid band")
    total = 0
    hits = 0
    for left, right, weight in spans:
        if right <= left:
            continue
        if left >= low and right <= high:
            total += (right - left) * weight
            hits += 1
    return [total, hits]

