def clipped_band_sum(low, high, spans):
    if high <= low:
        raise ValueError("band")
    total, hits = 0, 0
    for left, right, weight in spans:
        if right > left:
            ov = min(high, right) - max(low, left)
            if ov > 0:
                total += ov * weight
                hits += 1
    return [total, hits]

