def channel_highwater(events):
    marks, out = {}, []
    for kind, ch, seq in events:
        if kind == "msg":
            if seq < 1:
                raise ValueError("seq")
            prev = marks.get(ch, 0)
            out.append(seq - prev if seq > prev else 0)
            if seq > prev:
                marks[ch] = seq
        elif kind == "reset":
            marks.clear()
        else:
            raise ValueError("kind")
    return out

