def nested_batch_max(ops):
    cur, peak, out = 0, None, []
    for op_name, val in ops:
        if op_name == "add":
            cur += val
            if peak is None or cur > peak:
                peak = cur
        elif op_name == "soft":
            cur, peak = 0, None
        elif op_name == "hard":
            out.append(peak)
            cur, peak = 0, None
        else:
            raise ValueError("op")
    return out

