def atomic_kit_builds(inventory, kits):
    if any(qty < 0 for qty in inventory.values()):
        raise ValueError("stock")
    stock, out = dict(inventory), []
    for kit in kits:
        need = {}
        for part in kit:
            need[part] = need.get(part, 0) + 1
        ok = all(stock.get(part, 0) >= cnt for part, cnt in need.items())
        if ok:
            for part, cnt in need.items():
                stock[part] -= cnt
        out.append(ok)
    return out

