def panel_consensus(panels, threshold):
    if threshold < 1:
        raise ValueError("invalid threshold")
    counts = {}
    for panel in panels:
        for tag in panel:
            if tag:
                counts[tag] = counts.get(tag, 0) + 1
    return sorted(tag for tag, num in counts.items() if num >= threshold)

