def lru_pin_evictions(capacity, actions):
    if capacity < 1:
        raise ValueError("cap")
    order, pinned, out = [], set(), []
    for op, key in actions:
        if op == "put":
            if key not in order:
                if len(order) == capacity:
                    vic = order.pop(0)
                    pinned.discard(vic)
                    out.append(vic)
                order.append(key)
        elif op == "pin" and key in order:
            pinned.add(key)
        elif op == "unpin":
            pinned.discard(key)
        elif op != "pin":
            raise ValueError("op")
    return [out, order]

